import {objectToQuery} from '@jetbrains/teamcity-ui/dist/utils'
import plur from 'plur'
import {connect} from 'react-redux'

import withLazyLoading from '../../../hocs/withLazyLoading'
import type {State} from '../../../reducers/types'
import {getOverviewHref} from '../../../routes'
import {
  getBuildCompatibleAgents,
  getPipelineBatchIdFromBuildId,
  getPipelineIdFromBuildId,
  getPipelineJobIdFromBuildId,
  getPipelineRunIdFromBuildId,
} from '../../../selectors'
import type {BuildId} from '../../../types'
import {resolveWebEntityLink, WebEntityType} from '../../../utils/entityLinks'
import {Namespace} from '../../../utils/namespace'

import CompatibleAgents from './CompatibleAgents'
import {fetchCompatibleAgentsQueue} from './CompatibleAgents.actions'

const COMPATIBLE_AGENTS_LIMIT = 15

const getCompatibleAgentsLabel = (count?: number | null): string => {
  switch (count) {
    case null:
    case undefined:
      return 'Calculating...'

    case 0:
      return 'No agents'

    case 1:
      return '1 agent'

    case COMPATIBLE_AGENTS_LIMIT + 1:
      return `${COMPATIBLE_AGENTS_LIMIT}+ agents`

    default:
      return `${count} agents`
  }
}
const getCompatibleAgentsAnchorLabel = (count?: number | null): string => {
  switch (count) {
    case null:
    case undefined:
      return 'Calculating...'

    case 0:
      return 'Can run on no agents'

    case COMPATIBLE_AGENTS_LIMIT + 1:
      return `Can run on ${COMPATIBLE_AGENTS_LIMIT}+ agents`

    default:
      return `Can run on ${count} ${plur('agent', count)}`
  }
}

type OwnProps = {
  buildId: BuildId
  defaultVisible?: boolean
  className?: string
  withAnchor?: boolean
}
type StateProps = {
  label: string
  baseHref?: string | null
  secondary: boolean
  buildUrl?: string | null
  id: BuildId
  needsDetails: boolean
}

const mapStateToProps = (state: State, props: OwnProps): StateProps => {
  const {compatibleAgents, compatibleCloudImages} =
    getBuildCompatibleAgents(state, props.buildId) || {}
  const pipelineId = getPipelineIdFromBuildId(state, props.buildId)
  const runId = getPipelineRunIdFromBuildId(state, props.buildId)
  const jobId = getPipelineJobIdFromBuildId(state, props.buildId)
  const batchId = getPipelineBatchIdFromBuildId(state, props.buildId)
  const count =
    compatibleAgents?.count != null && compatibleCloudImages?.count != null
      ? compatibleAgents.count + compatibleCloudImages.count
      : null
  const href = pipelineId
    ? `${getOverviewHref({pipelineId, runId})}${jobId ? '?' : ''}${objectToQuery({job: jobId, pageFullLogBuildId: batchId})}`
    : `${resolveWebEntityLink(WebEntityType.BUILD, props.buildId)}&tab=queuedBuildCompatibilityTab`
  return {
    label: props.withAnchor
      ? getCompatibleAgentsAnchorLabel(count)
      : getCompatibleAgentsLabel(count),
    baseHref: href,
    secondary: count == null,
    buildUrl: href,
    id: props.buildId,
    needsDetails: compatibleAgents == null || compatibleCloudImages == null,
  }
}

type ActionProps = {
  fetchDetails(id: BuildId): void
}

const actionCreators: ActionProps = {
  fetchDetails: fetchCompatibleAgentsQueue,
}

const CompatibleAgentsWithLazyLoading = withLazyLoading<
  BuildId,
  OwnProps & StateProps & ActionProps
>({
  namespace: Namespace.AGENTS,
})(CompatibleAgents)
export default connect(mapStateToProps, actionCreators)(CompatibleAgentsWithLazyLoading)
