import {graphql} from 'react-relay'

export const compatibleAgentsQuery = graphql`
  query CompatibleAgentsQuery($buildLocator: String!) {
    build(buildLocator: $buildLocator) {
      id
      compatibleAgents(locator: "count:16") {
        count
      }
      compatibleCloudImages(locator: "count:16") {
        count
      }
    }
  }
`
