import {
  ControlsHeight,
  ControlsHeightContext,
} from '@jetbrains/ring-ui-built/components/global/controls-height'
import classNames from 'classnames'
import {memo} from 'react'

import {useBuildTitle} from '../../../../hooks/useBuildTitle'
import useDocumentTitle from '../../../../hooks/useDocumentTitle'
import {getBuild, getBuildStatusType} from '../../../../selectors'
import {stringifyId} from '../../../../types'
import {StatusBadge, TimeBadge} from '../../../common/Badges'
import AgentBadge from '../../../common/Badges/AgentBadge/AgentBadge'
import BuildTypeInvestigationsBadge from '../../../common/Badges/BuildTypeInvestigationsBadge/BuildTypeInvestigationsBadge'
import ResponsiveBadgeContainer from '../../../common/Badges/ResponsiveBadgeContainer/ResponsiveBadgeContainer'
import {useDurationInfo} from '../../../common/Badges/TimeBadge/TimeBadge.hooks'
import BuildActionsDropdown from '../../../common/BuildActionsDropdown/BuildActionsDropdown'
import Description from '../../../common/Description/Description.container'
import EditEntity from '../../../common/EditEntity/EditEntity.container'
import NoWrap from '../../../common/NoWrap/NoWrap'
import PageTitle from '../../../common/PageTitle/PageTitle'
import RunBuild from '../../../common/RunBuild/RunBuild.container'
import SequenceLoader from '../../../common/SequenceLoader/SequenceLoader'
import StarBuild from '../../../common/StarBuild/StarBuild.container'
import StopBuild from '../../../common/StopBuild/StopBuild.container'
import {useIsCancellable} from '../../../common/StopBuild/StopBuild.hooks'
import {getIsInterrupted} from '../../../common/StopBuild/StopBuild.selectors'
import {StopButtonType} from '../../../common/StopBuild/StopBuild.types'
import BranchLabelBadge from '../BranchLabelBadge/BranchLabelBadge'

import type {Props} from './BuildPageHeader.types'
import BuildTypeInfoPopup from './BuildTypeInfoPopup/BuildTypeInfoPopup.container'
import PersonalBuildStatusIcon from './PersonalBuildStatusIcon/PersonalBuildStatusIcon'

import styles from './BuildPageHeader.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

function BuildPageHeader({
  buildTypeName,
  buildId,
  buildTypeId,
  projectId,
  status,
  branch,
  state,
  personal,
}: Props) {
  const title = useBuildTitle(buildId)

  const isQueued = state === 'queued'
  const isRunning = state === 'running'

  const isSuccess = status === 'SUCCESS'

  useDocumentTitle(`${buildTypeName} / ${title} — TeamCity`)

  const {duration, queueDuration, estimatedDuration, date} = useDurationInfo(buildId)
  const isCancellable = useIsCancellable(buildId)
  const showStopButton = useAppSelector(
    reduxState =>
      (isRunning || isQueued) && (isCancellable || getIsInterrupted(reduxState, buildId)),
  )
  const statusType = useAppSelector(reduxState => getBuildStatusType(reduxState, buildId))
  const statusChangeComment = useAppSelector(
    reduxState => getBuild(reduxState, buildId)?.statusChangeComment,
  )
  const canceledInfo = useAppSelector(reduxState => getBuild(reduxState, buildId)?.canceledInfo)
  const waitReason = useAppSelector(reduxState => getBuild(reduxState, buildId)?.waitReason)
  const failedToStart = useAppSelector(reduxState => getBuild(reduxState, buildId)?.failedToStart)
  const queuePosition = useAppSelector(reduxState => getBuild(reduxState, buildId)?.queuePosition)

  return projectId != null && buildTypeId != null && buildId != null ? (
    <>
      <div className={styles.top}>
        <PageTitle className={styles.heading}>
          {personal && <PersonalBuildStatusIcon buildId={buildId} isQueued={isQueued} />}
          <span className={classNames(styles.title)}>{title}</span>
          <NoWrap>
            <StarBuild className={styles.star} buildId={buildId} showEmpty />
          </NoWrap>
        </PageTitle>
        <ControlsHeightContext.Provider value={ControlsHeight.M}>
          <SequenceLoader className={styles.topSequenceLoader} loader="" reverse>
            {showStopButton && (
              <StopBuild
                seqKey="StopBuild"
                buildId={buildId}
                buttonType={StopButtonType.ICON_BUTTON}
                withBorder
              />
            )}
            <RunBuild
              seqKey="RunBuild"
              buildTypeId={buildTypeId}
              withVisibilityDetect={false}
              branch={branch}
              redirectToQueuedBuild
              isPrimary
            />
            <BuildActionsDropdown key={state} seqKey="Actions" withHint hintEntityName="build" />
            <EditEntity seqKey="EditEntity" />
          </SequenceLoader>
        </ControlsHeightContext.Provider>
      </div>
      <div className={styles.main}>
        <div className={styles.headerInfo}>
          <Description className={styles.description} lines={2} buildId={buildId} />
        </div>
        <div className={styles.leftColumn}>
          <ResponsiveBadgeContainer>
            <StatusBadge
              seqKey={'statusBadge'}
              buildTypeId={buildTypeId}
              status={statusType}
              statusChangeComment={statusChangeComment}
              canceledInfo={canceledInfo}
              waitReason={waitReason}
              failedToStart={failedToStart}
              isRunning={isRunning}
            />
            <BranchLabelBadge seqKey="branchLabelBadge" buildId={buildId} />
            <TimeBadge
              seqKey={'timeBadge'}
              dataTestId={'time-badge'}
              className={styles.timeBadge}
              duration={duration}
              estimatedDuration={estimatedDuration}
              queueDuration={queueDuration}
              queuePosition={queuePosition}
              date={date}
              title={'Duration'}
              clickable={false}
              isQueued={isQueued}
              isRunning={isRunning}
              buildId={buildId}
            />
            <AgentBadge
              seqKey="agentBadge"
              dataTestId={'agent-badge'}
              buildId={buildId}
              className={styles.agentBadge}
              isShowCompatibleAgents
            />
            {!isQueued && !(isSuccess && isRunning) && (
              <BuildTypeInvestigationsBadge
                seqKey="investigationsBadge"
                buildTypeId={buildTypeId}
              />
            )}
          </ResponsiveBadgeContainer>
        </div>
        <div className={styles.rightColumn}>
          <BuildTypeInfoPopup
            key={stringifyId(buildTypeId)}
            buildTypeId={buildTypeId}
            buildId={buildId}
          />
        </div>
      </div>
    </>
  ) : null
}
export default memo(BuildPageHeader)
