import type {TooltipProps} from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import RingTooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {useMemo} from 'react'

import styles from './Tooltip.module.css'

function Tooltip({children, popupProps, ...props}: TooltipProps) {
  const tooltipPopupProps = useMemo(
    () => ({
      className: styles.tooltip,
      ...popupProps,
    }),
    [popupProps],
  )

  return (
    <RingTooltip delay={500} popupProps={tooltipPopupProps} {...props}>
      {children}
    </RingTooltip>
  )
}

export default Tooltip
