import {skipToken} from '@reduxjs/toolkit/query'
import type {ReactNode} from 'react'
import {useEffect} from 'react'
import type {EntryPointProps, PreloadedQuery} from 'react-relay'
import {usePreloadedQuery} from 'react-relay'
import {useParams} from 'react-router'

import {EntityRedirect} from '../../../containers/EntityLink'
import {getBuildTypeArg} from '../../../rest/buildTypes'
import {getPipelineHref} from '../../../routes'
import {getBuild, getBuildType, getProject} from '../../../selectors'
import {restApi} from '../../../services/rest'
import {toBuildTypeId} from '../../../types'
import type {PreloadedEntryPoints} from '../../../types/entryPoints'
import {extractError} from '../../../utils/extractError'
import {subscribeOnBuildTypeEvents} from '../../../utils/subscriber'
import {BUILD_TYPE_UPDATED} from '../../../utils/subscriptionEvents'
import Loader from '../../common/Loader/Loader'
import Redirect from '../../common/Redirect/Redirect'
import {useRefetchBuildTypeOnPermissionsChange} from '../BuildTypePage/BuildTypePage.hooks'

import type {BuildPageQuery} from './__generated__/BuildPageQuery.graphql'
import type {BuildArtifactsTabEntryPoint} from './BuildArtifactsTab/BuildArtifactsTab.entryPoint'
import type {BuildChangesTabEntryPoint} from './BuildChangesTab/BuildChangesTab.entryPoint'
import type {BuildOverviewTabEntryPoint} from './BuildOverviewTab/BuildOverviewTab.entryPoint'
import BuildPage from './BuildPage'
import {useBuildPageData} from './BuildPage.hooks'
import {query} from './BuildPage.queries'
import type {BuildParametersTabEntryPoint} from './BuildParametersTab/BuildParametersTab.entryPoint'
import type {BuildTestsTabEntryPoint} from './BuildTestsTab/BuildTestsTab.entryPoint'
import type {DependenciesTabEntryPoint} from './DependenciesTab/DependenciesTab.entryPoint'

import {useAppSelector} from 'src/hooks/react-redux'

export type NestedEntryPoints = {
  overviewTab?: typeof BuildOverviewTabEntryPoint
  dependenciesTab?: typeof DependenciesTabEntryPoint
  testsTab?: typeof BuildTestsTabEntryPoint
  parametersTab?: typeof BuildParametersTabEntryPoint
  artifactsTab?: typeof BuildArtifactsTabEntryPoint
  changesTab?: typeof BuildChangesTabEntryPoint
}
type Props = {
  entryPoints: PreloadedEntryPoints<NestedEntryPoints>
}
function BuildPageContainer(props: Props) {
  const {
    buildTypeIdChanged,
    buildLoaded,
    buildError,
    listError,
    actualBuildTypeId,
    buildTypeId,
    buildIdChanged,
    actualBuildId,
    buildLocator,
    branch,
  } = useBuildPageData()

  const buildState = useAppSelector(state => getBuild(state, actualBuildId)?.state)
  const projectId = useAppSelector(state => getBuildType(state, actualBuildTypeId)?.projectId)
  const queued = useAppSelector(state => getBuild(state, actualBuildId)?.state === 'queued')

  const projectLoaded = useAppSelector(state => Boolean(getProject(state, projectId)))
  const buildTypeLoaded = useAppSelector(state => getBuildType(state, actualBuildTypeId) != null)
  const {refetch: refetchBuildType} = restApi.endpoints.getBuildTypeNormalized.useQuerySubscription(
    actualBuildTypeId != null ? getBuildTypeArg(actualBuildTypeId) : skipToken,
  )
  const buildTypeInternalId = useAppSelector(
    state => getBuildType(state, actualBuildTypeId)?.internalId,
  )
  useEffect(
    () =>
      buildTypeInternalId != null
        ? subscribeOnBuildTypeEvents(buildTypeInternalId, [BUILD_TYPE_UPDATED], refetchBuildType)
        : undefined,
    [buildTypeInternalId, refetchBuildType],
  )

  if (buildTypeIdChanged || buildIdChanged) {
    return (
      <EntityRedirect
        buildId={actualBuildId}
        buildTypeId={actualBuildTypeId}
        redirectedFromId={buildTypeIdChanged ? buildTypeId : undefined}
      />
    )
  }

  const error = extractError(buildError) || listError

  if (!window.GLOBAL_ERROR_PAGE_DISABLED && error != null) {
    throw error
  }

  return actualBuildId != null ? (
    <BuildPage
      buildId={actualBuildId}
      buildLocator={buildLocator}
      buildTypeId={actualBuildTypeId}
      projectId={projectId}
      branch={branch}
      buildState={buildState}
      queued={queued}
      buildLoaded={buildLoaded}
      buildTypeLoaded={buildTypeLoaded}
      projectLoaded={projectLoaded}
      {...props}
    />
  ) : (
    <Loader />
  )
}

type Queries = {main: BuildPageQuery}

interface RedirectProps {
  mainQuery: PreloadedQuery<BuildPageQuery>
  children: ReactNode
}

function BuildPagePipelineRedirect(props: RedirectProps) {
  const {mainQuery, children} = props
  const {buildId} = useParams()
  const {pipelineRun, pipelineRunJob} = usePreloadedQuery(query, mainQuery)?.build ?? {}
  const isHead = pipelineRun != null
  const pipelineId = pipelineRun?.pipeline?.id ?? pipelineRunJob?.pipelineRun?.pipeline?.id
  const pipelineRunId = isHead ? buildId : String(pipelineRunJob?.pipelineRun?.build?.id)

  return !IS_STORYBOOK && pipelineId != null && pipelineRunId != null ? (
    <Redirect to={getPipelineHref(pipelineId, pipelineRunId) + (isHead ? '' : `?job=${buildId}`)} />
  ) : (
    children
  )
}

export default function BuildPageOuterContainer({
  queries,
  entryPoints,
}: EntryPointProps<Queries, NestedEntryPoints, {}, {}>) {
  const {buildId, buildTypeId} = useParams()
  useRefetchBuildTypeOnPermissionsChange(
    buildTypeId != null ? toBuildTypeId(buildTypeId) : undefined,
  )

  return (
    <BuildPagePipelineRedirect mainQuery={queries.main}>
      <BuildPageContainer key={buildId} entryPoints={entryPoints} />
    </BuildPagePipelineRedirect>
  )
}
export type BuildPageComponent = typeof BuildPageOuterContainer
