import {Tabs, CustomItem} from '@jetbrains/ring-ui-built/components/tabs/tabs'
import {skipToken} from '@reduxjs/toolkit/query'
import {memo, useMemo, useCallback, Suspense, useEffect} from 'react'
import {EntryPointContainer} from 'react-relay'
import {useLocation, useNavigate} from 'react-router'

import BuildsFetcher from '../../../containers/BuildsFetcher'
import {EntityProvider} from '../../../contexts/entity'
import {useQueryParam} from '../../../hooks/routes'
import {useTabs} from '../../../hooks/useTabs'
import {getSingleProjectArg} from '../../../rest/projects'
import {getHrefWithQueryParams} from '../../../routes'
import {calcNextTab, getBuildType, getTabUrl} from '../../../selectors'
import {restApi} from '../../../services/rest'
import {BuildPageTabNamesEnum, BuildPageTabTitlesEnum, stringifyId} from '../../../types'
import type {Tab, TabId} from '../../../types'
import {emptyArray} from '../../../utils/empty'
import {subscribeOnBuildTypeEvents} from '../../../utils/subscriber'
import {
  BUILD_FINISHED,
  BUILD_INTERRUPTED,
  BUILD_TYPE_REMOVED_FROM_QUEUE,
} from '../../../utils/subscriptionEvents'
import {parseTabTitle} from '../../../utils/tabs'
import ClassicUITabAdapter from '../../common/ClassicUITabAdapter/ClassicUITabAdapter'
import Loader from '../../common/Loader/Loader'
import OverviewTab, {renderTitle} from '../../common/OverviewTab/OverviewTab'
import tabStyles from '../../common/OverviewTab/OverviewTab.module.css'
import TabPlugin from '../../common/Plugin/TabPlugin/TabPlugin'
import TabsLoader from '../../common/TabsLoader/TabsLoader'
import BuildLogTab from '../../packages/BuildLog/BuildLogTab/BuildLogTab.container'

import type {Props} from './BuildPage.types'
import BuildPageHeader from './BuildPageHeader/BuildPageHeader.container'
import {buildParametersTabParam} from './BuildParametersTab/BuildParameters.consts'
import {BuildParametersKindTab} from './BuildParametersTab/BuildParameters.types'
import DependenciesTab from './DependenciesTab/DependenciesTab.lazy'

import {useAppSelector} from 'src/hooks/react-redux'

const BuildPage = (props: Props) => {
  const {
    buildTypeId,
    buildId,
    buildLocator,
    buildLoaded,
    buildTypeLoaded,
    projectLoaded,
    queued,
    buildState,
    entryPoints,
  } = props

  const buildParameterTab = useQueryParam(buildParametersTabParam)

  const location = useLocation()
  const navigate = useNavigate()
  const currentTabId = useQueryParam('buildTab')
  const currentTab = useAppSelector(state => calcNextTab(state, {tab: currentTabId, buildId}))
  const {
    tabs: {sakuraTabs, classicTabs},
    allTabsReady,
    refetchTabs,
  } = useTabs(props)
  const buildTypeInternalId = useAppSelector(state => getBuildType(state, buildTypeId)?.internalId)
  const projectId = useAppSelector(state => getBuildType(state, buildTypeId)?.projectId)
  restApi.endpoints.getProjectNormalized.useQuerySubscription(
    projectId ? getSingleProjectArg(projectId, {withAncestorProjects: true}) : skipToken,
  )

  useEffect(
    () =>
      buildTypeInternalId != null
        ? subscribeOnBuildTypeEvents(
            buildTypeInternalId,
            [BUILD_FINISHED, BUILD_INTERRUPTED, BUILD_TYPE_REMOVED_FROM_QUEUE],
            refetchTabs,
          )
        : undefined,
    [buildTypeInternalId, refetchTabs],
  )

  const onSelect = useCallback(
    (buildTab: TabId) =>
      navigate(
        getHrefWithQueryParams(location, null, ({branch}) => ({buildTab, branch})),
        {preventScrollReset: true},
      ),
    [location, navigate],
  )

  const overviewTab = useMemo(
    () =>
      entryPoints.overviewTab && (
        <EntryPointContainer
          entryPointReference={entryPoints.overviewTab}
          props={{buildId, buildLocator}}
        />
      ),
    [entryPoints.overviewTab, buildId, buildLocator],
  )
  const testsTab = useMemo(
    () =>
      entryPoints.testsTab && (
        <EntryPointContainer
          entryPointReference={entryPoints.testsTab}
          props={{buildId, buildLocator}}
        />
      ),
    [entryPoints.testsTab, buildId, buildLocator],
  )

  const getImplementedInSakuraUITabs = useCallback(
    (id: TabId) => {
      switch (id) {
        case BuildPageTabNamesEnum.OVERVIEW:
          return overviewTab
        case BuildPageTabNamesEnum.CHANGES:
          return (
            entryPoints.changesTab && (
              <EntryPointContainer entryPointReference={entryPoints.changesTab} props={{}} />
            )
          )
        case BuildPageTabNamesEnum.DEPENDENCIES:
          return <DependenciesTab buildId={buildId} entryPoint={entryPoints.dependenciesTab} />
        case BuildPageTabNamesEnum.LOG:
          return <BuildLogTab buildId={buildId} />
        case BuildPageTabNamesEnum.TESTS:
          return testsTab
        case BuildPageTabNamesEnum.ARTIFACTS:
          return (
            entryPoints.artifactsTab && (
              <EntryPointContainer
                entryPointReference={entryPoints.artifactsTab}
                props={{buildId}}
              />
            )
          )
        case BuildPageTabNamesEnum.PARAMETERS:
          return entryPoints.parametersTab ? (
            <EntryPointContainer
              entryPointReference={entryPoints.parametersTab}
              props={{buildId}}
            />
          ) : null
        default:
          return null
      }
    },
    [overviewTab, buildId, entryPoints, testsTab],
  )
  const renderTab = useCallback(
    (tab?: Tab) => {
      let tabId = currentTab
      let titleText =
        BuildPageTabTitlesEnum[currentTab] ??
        stringifyId(currentTab).charAt(0).toUpperCase() + stringifyId(currentTab).slice(1)
      let title = renderTitle(titleText)

      if (tab != null) {
        const {name, counter} = parseTabTitle(tab.title)
        tabId = tab.id
        titleText = name
        title = renderTitle(name, counter)
      }

      const tabContent = getImplementedInSakuraUITabs(tabId)
      const Wrapper = tab?.sakura === true ? TabPlugin : ClassicUITabAdapter

      return (
        <OverviewTab
          key={stringifyId(tabId)}
          id={tabId}
          title={title}
          titleProps={{'aria-label': titleText}}
          isClassic={
            tabContent == null ||
            (tabId === BuildPageTabNamesEnum.PARAMETERS &&
              buildParameterTab === BuildParametersKindTab.STATISTICS)
          }
          href={getTabUrl({buildId, buildTypeId}, tabId)}
        >
          <Suspense fallback={<Loader data-suspense-fallback />}>
            {tabContent || (
              <Wrapper
                tabId={tabId}
                title={titleText}
                buildId={buildId}
                queued={queued}
                js={tab?.js}
                css={tab?.css}
                url={tab?.url}
              />
            )}
          </Suspense>
        </OverviewTab>
      )
    },
    [currentTab, getImplementedInSakuraUITabs, buildId, buildTypeId, queued, buildParameterTab],
  )
  const classicUITabs = useMemo(
    () => (classicTabs.length > 0 ? classicTabs.map(renderTab) : emptyArray),
    [renderTab, classicTabs],
  )
  const sakuraUITabs = useMemo(
    () => (sakuraTabs.length ? sakuraTabs.map(renderTab) : [renderTab()]),
    [sakuraTabs, renderTab],
  )
  return useMemo(
    () => (
      <EntityProvider buildId={buildId}>
        <BuildsFetcher
          locator={`id:${stringifyId(buildId)}`}
          buildTypeId={buildTypeId}
          withQueued
          withRunning
        >
          {buildLoaded && buildTypeLoaded && projectLoaded ? (
            <>
              <BuildPageHeader buildId={buildId} />
              <Tabs
                className={tabStyles.tabs}
                key={`${stringifyId(buildId)}${buildState === 'queued' ? '_queued' : ''}`}
                selected={currentTab}
                onSelect={onSelect}
                data-test="overview-tabs-panel"
                initialVisibleItems={5}
                autoCollapse={process.env.NODE_ENV !== 'test'}
              >
                {sakuraUITabs}
                {classicUITabs}
                {!allTabsReady ? (
                  <CustomItem key="tabs_loader">
                    <TabsLoader />
                  </CustomItem>
                ) : null}
              </Tabs>
            </>
          ) : (
            <Loader />
          )}
        </BuildsFetcher>
      </EntityProvider>
    ),
    [
      buildId,
      buildTypeId,
      buildLoaded,
      buildTypeLoaded,
      projectLoaded,
      buildState,
      currentTab,
      onSelect,
      sakuraUITabs,
      classicUITabs,
      allTabsReady,
    ],
  )
}

export default memo(BuildPage)
