import {useAppSelector} from '../../../../hooks/react-redux'
import {getBuild} from '../../../../selectors'
import Badge from '../../../common/Badge/Badge'
import type {BuildBranchOwnProps} from '../../../common/BranchLabel/BranchLabel.types'
import BuildTypeBranchLabel from '../../../common/BranchLabel/BuildTypeBranchLabel.container'
import {useSequenceLoaderReadyHandler} from '../../../common/SequenceLoader/SequenceLoader.hooks'
import type {SeqProps} from '../../../common/SequenceLoader/SequenceLoader.types'

import styles from './BranchLabelBadge.module.css'

function BranchLabelBadge({buildId}: BuildBranchOwnProps & SeqProps) {
  const {branchName, defaultBranch, buildType} =
    useAppSelector(state => getBuild(state, buildId)) ?? {}
  useSequenceLoaderReadyHandler(true)

  if (!branchName) {
    return null
  }
  return (
    <Badge
      dataTestId={'branch-label-badge'}
      label={'Branch'}
      className={styles.badge}
      labelClassName={styles.branchLabel}
    >
      <BuildTypeBranchLabel
        nameClassName={styles.branchName}
        visibleNameClassName={styles.text}
        className={styles.branch}
        buildId={buildId}
        tailLength={10}
        title={null}
        withIcon
        withTooltip
        inline
        main={defaultBranch}
        name={branchName}
        buildTypeId={buildType}
      />
    </Badge>
  )
}

export default BranchLabelBadge
